// ValidateCreateRequestBody runs the validations defined on CreateRequestBody
func ValidateCreateRequestBody(body *CreateRequestBody) (err error) {
	if body.Request == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("request", "body"))
	}
	if body.CreatedBy != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.createdBy", *body.CreatedBy, goa.FormatEmail))
	}
	if body.Request != nil {
		if err2 := ValidateDevBuildSpecRequestBody(body.Request); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	return
}

// ValidateDevBuildSpecRequestBody runs the validations defined on
// DevBuildSpecRequestBody
func ValidateDevBuildSpecRequestBody(body *DevBuildSpecRequestBody) (err error) {
	if body.Product == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("product", "body"))
	}
	if body.Edition == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("edition", "body"))
	}
	if body.GitRef == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("gitRef", "body"))
	}
	if body.Edition != nil {
		if !(*body.Edition == "enterprise" || *body.Edition == "community" || *body.Edition == "fips" || *body.Edition == "failpoint" || *body.Edition == "experiment" || *body.Edition == "nextgen" || *body.Edition == "next-gen") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.edition", *body.Edition, []any{"enterprise", "community", "fips", "failpoint", "experiment", "nextgen", "next-gen"}))
		}
	}
	if body.Platform != nil {
		if !(*body.Platform == "all" || *body.Platform == "linux" || *body.Platform == "darwin" || *body.Platform == "linux/amd64" || *body.Platform == "linux/arm64" || *body.Platform == "darwin/amd64" || *body.Platform == "darwin/arm64") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.platform", *body.Platform, []any{"all", "linux", "darwin", "linux/amd64", "linux/arm64", "darwin/amd64", "darwin/arm64"}))
		}
	}
	if body.PipelineEngine != nil {
		if !(*body.PipelineEngine == "jenkins" || *body.PipelineEngine == "tekton") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.pipelineEngine", *body.PipelineEngine, []any{"jenkins", "tekton"}))
		}
	}
	if body.Product != nil {
		if !(*body.Product == "dm" || *body.Product == "enterprise-plugin" || *body.Product == "ng-monitoring" || *body.Product == "pd" || *body.Product == "ticdc" || *body.Product == "ticdc-newarch" || *body.Product == "tici" || *body.Product == "tidb" || *body.Product == "br" || *body.Product == "dumpling" || *body.Product == "tidb-lightning" || *body.Product == "tidb-binlog" || *body.Product == "drainer" || *body.Product == "pump" || *body.Product == "tidb-dashboard" || *body.Product == "tidb-operator" || *body.Product == "tidb-tools" || *body.Product == "tiflash" || *body.Product == "tikv" || *body.Product == "tiproxy" || *body.Product == "tidb-cse" || *body.Product == "pd-cse" || *body.Product == "tidb-operator-cse" || *body.Product == "cassandra-on-mysql" || *body.Product == "qdrant-on-tidb") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.product", *body.Product, []any{"dm", "enterprise-plugin", "ng-monitoring", "pd", "ticdc", "ticdc-newarch", "tici", "tidb", "br", "dumpling", "tidb-lightning", "tidb-binlog", "drainer", "pump", "tidb-dashboard", "tidb-operator", "tidb-tools", "tiflash", "tikv", "tiproxy", "tidb-cse", "pd-cse", "tidb-operator-cse", "cassandra-on-mysql", "qdrant-on-tidb"}))
		}
	}
	return
}
